$year=DB::table('academic_years')->where('name','2026/2027')->value('id')?:DB::table('academic_years')->insertGetId(['name'=>'2026/2027','starts_on'=>'2026-08-01','ends_on'=>'2027-07-31','is_current'=>1,'is_closed'=>0,'created_at'=>now(),'updated_at'=>now()]);
