foreach([[100,'лекция'],[200,'практика'],[300,'курсовая'],[400,'зачет']] as $x)DB::table('study_types')->updateOrInsert(['source_id'=>$x[0]],['name'=>$x[1],'created_at'=>now(),'updated_at'=>now()]);
